+    #[test]
+    fn store_powershell_joins_its_job_while_another_instance_runs() {
+        struct Guarded {
+            process: Process,
+            _server: OwnedHandle,
+        }
+        impl Drop for Guarded {
+            fn drop(&mut self) {
+                self.process.kill();
+            }
+        }
+
