+            "opencode-pty-store-pwsh-gate-{:032x}",
+            rand::random::<u128>()
+        )));
+        std::fs::write(&gate.0, "").unwrap();
+        let gate_arg = gate.0.display().to_string().replace('\'', "''");
+
+        let start = |id, command: &str| {
+            let mut request = test_request(
+                alias,
+                &[
+                    "-NoLogo",
+                    "-NoProfile",
+                    "-NonInteractive",
+                    "-Command",
+                    command,
+                ],
+            );
